# ❌ OLD: Manually parsing headers string, no Swagger /docs auth integration,
# and permissions must be manually checked in every endpoint.
from fastapi import FastAPI, Header, HTTPException
import jwt

app = FastAPI()

@app.get('/admin/data')
def get_admin_data(authorization: str = Header(None)):
  if not authorization or not authorization.startswith('Bearer '):
    raise HTTPException(status_code=401, detail='Missing Bearer token')
  token = authorization.split(' ')[1]
  payload = jwt.decode(token, 'SECRET', algorithms=['HS256'])
  if 'admin' not in payload.get('roles', []):
    raise HTTPException(status_code=403, detail='Insufficient permissions')
  return {'secret': 'data'}

from fastapi import FastAPI, Depends, HTTPException, Security, status
from fastapi.security import OAuth2PasswordBearer, SecurityScopes
import jwt

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl='token', scopes={'admin': 'Admin access'})

async def get_current_user(security_scopes: SecurityScopes, token: str = Depends(oauth2_scheme)):
  try:
    payload = jwt.decode(token, 'SECRET_KEY', algorithms=['HS256'])
  except jwt.PyJWTError:
    raise HTTPException(status_code=401, detail='Invalid token')

  token_scopes = payload.get('scopes', [])
  for scope in security_scopes.scopes:
    if scope not in token_scopes:
      raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail='Not enough permissions')
  return payload

# ✅ NEW: Declarative permission check with automatic Swagger UI OAuth2 button
@app.get('/admin/data')
async def get_admin_data(current_user = Security(get_current_user, scopes=['admin'])):
  return {'secret': 'data', 'user': current_user['sub']}
